$id = function ($table, $alias, $where = '') use ($db) {
    $found = $db->setQuery('SELECT id FROM ' . $table . ' WHERE alias = ' . $db->quote($alias) . $where . ' ORDER BY id LIMIT 1')->loadResult();
    if (!$found) {
        throw new RuntimeException("Not found in $table: $alias");
    }
    return (int) $found;
};

$insert = function ($table, $row) use ($db) {
    $query = $db->getQuery(true)->insert($table)->columns(array_map([$db, 'quoteName'], array_keys($row)))
        ->values(implode(',', array_map(fn ($value) => $value === null ? 'NULL' : $db->quote($value), $row)));
    $db->setQuery($query)->execute();
    return (int) $db->insertid();
};

// The nested set of a table (lft, rgt, level and path), from parent_id; new rows (lft 0) go after their siblings.
$rebuild = function ($table, $parent = 1, $left = 0, $level = 0, $path = '') use ($db, &$rebuild) {
    $right = $left + 1;
    $children = $db->setQuery('SELECT id, alias FROM ' . $table . ' WHERE parent_id = ' . (int) $parent . ' ORDER BY lft = 0, lft, id')->loadObjectList();
    foreach ($children as $child) {
        $right = $rebuild($table, $child->id, $right, $level + 1, ltrim($path . '/' . $child->alias, '/'));
    }
    $db->setQuery('UPDATE ' . $table . ' SET lft = ' . $left . ', rgt = ' . $right . ', level = ' . $level . ', path = ' . $db->quote($path) . ' WHERE id = ' . (int) $parent)->execute();
    return $right + 1;
};

